(async () => {
  try {
    const page = figma.currentPage;

    // 1. Decodificar la imagen PNG original (512x512)
    const base64Data = "";
    const binStr = atob(base64Data);
    const bytes = new Uint8Array(binStr.length);
    for (let i = 0; i < binStr.length; i++) {
      bytes[i] = binStr.charCodeAt(i);
    }
    const figmaImage = figma.createImage(bytes);

    // 2. Crear Frame Contenedor para el Sistema de Logos
    const logoContainer = figma.createFrame();
    logoContainer.name = "Asset - Logo Presupuesto Estudiantil";
    logoContainer.x = figma.viewport.center.x - 400;
    logoContainer.y = figma.viewport.center.y - 300;
    logoContainer.resize(800, 600);
    logoContainer.fills = [{ type: 'SOLID', color: { r: 0.95, g: 0.96, b: 0.98 } }];
    logoContainer.cornerRadius = 16;
    logoContainer.layoutMode = 'VERTICAL';
    logoContainer.itemSpacing = 24;
    logoContainer.paddingLeft = 32;
    logoContainer.paddingRight = 32;
    logoContainer.paddingTop = 32;
    logoContainer.paddingBottom = 32;
    logoContainer.primaryAxisSizingMode = 'AUTO';
    logoContainer.counterAxisSizingMode = 'AUTO';
    page.appendChild(logoContainer);

    // Título del Componente
    await figma.loadFontAsync({ family: "Inter", style: "Bold" });
    await figma.loadFontAsync({ family: "Inter", style: "Regular" });
    
    const title = figma.createText();
    logoContainer.appendChild(title);
    title.fontName = { family: "Inter", style: "Bold" };
    title.characters = "Identidad Visual · Logo Presupuesto Estudiantil";
    title.fontSize = 20;
    title.fills = [{ type: 'SOLID', color: { r: 0.05, g: 0.1, b: 0.2 } }];

    const row = figma.createFrame();
    logoContainer.appendChild(row);
    row.layoutMode = 'HORIZONTAL';
    row.itemSpacing = 40;
    row.fills = [];
    row.layoutSizingHorizontal = 'HUG';
    row.layoutSizingVertical = 'HUG';

    // A. Variante 1: Logo Vectorial Nativo (SVG Editable)
    const svgCode = `<svg width="512" height="512" viewBox="0 0 512 512" fill="none" xmlns="http://www.w3.org/2000/svg">
      <circle cx="256" cy="256" r="240" fill="#0B192C"/>
      <circle cx="256" cy="256" r="207.5" stroke="#0284C7" stroke-width="19"/>
      <path d="M153 248 V318 C153 346 198 360 256 360 C314 360 359 346 359 318 V248 L256 298 Z" fill="#FFFFFF"/>
      <path d="M256 121 L421 200 L256 280 L90 200 Z" fill="#FFFFFF"/>
      <line x1="391.5" y1="202" x2="391.5" y2="295" stroke="#16A34A" stroke-width="14" stroke-linecap="round"/>
      <circle cx="391.5" cy="312" r="23.5" fill="#16A34A"/>
      <path d="M174 412 C222 438 290 438 338 412" stroke="#1D4ED8" stroke-width="18" stroke-linecap="round" fill="none"/>
    </svg>`;

    const vectorLogo = figma.createNodeFromSvg(svgCode);
    vectorLogo.name = "Logo (Vectorial SVG 512px)";
    row.appendChild(vectorLogo);

    // B. Variante 2: Logo Oficial Imagen HD (512px)
    const imgCol = figma.createFrame();
    row.appendChild(imgCol);
    imgCol.layoutMode = 'VERTICAL';
    imgCol.itemSpacing = 16;
    imgCol.fills = [];
    imgCol.layoutSizingHorizontal = 'HUG';
    imgCol.layoutSizingVertical = 'HUG';

    const imgNode512 = figma.createFrame();
    imgNode512.name = "Logo (Asset Oficial HD 512px)";
    imgNode512.resize(512, 512);
    imgNode512.fills = [{
      type: 'IMAGE',
      imageHash: figmaImage.hash,
      scaleMode: 'FIT'
    }];
    imgCol.appendChild(imgNode512);

    // C. Variante 3: Versión Navbar (48px lista para usar)
    const navCol = figma.createFrame();
    row.appendChild(navCol);
    navCol.layoutMode = 'VERTICAL';
    navCol.itemSpacing = 12;
    navCol.fills = [];
    navCol.layoutSizingHorizontal = 'HUG';
    navCol.layoutSizingVertical = 'HUG';

    const lbl = figma.createText();
    navCol.appendChild(lbl);
    lbl.fontName = { family: "Inter", style: "Regular" };
    lbl.characters = "Tamaño Navbar (48px):";
    lbl.fontSize = 13;
    lbl.fills = [{ type: 'SOLID', color: { r: 0.3, g: 0.35, b: 0.45 } }];

    const imgNode48 = figma.createFrame();
    imgNode48.name = "Logo (Tamaño Navbar 48px)";
    imgNode48.resize(48, 48);
    imgNode48.fills = [{
      type: 'IMAGE',
      imageHash: figmaImage.hash,
      scaleMode: 'FIT'
    }];
    navCol.appendChild(imgNode48);

    figma.viewport.scrollAndZoomIntoView([logoContainer]);
    console.log("✅ ¡Logo replicado idéntico con éxito en Figma!");
  } catch (err) {
    console.error("Error al replicar el logo:", err);
  }
})();
